const fs = require('fs');

const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(BigInt);
const MOD = 998244353n;
let pow;

function init(n, k) {
    pow = new Array(k);
    pow[0] = 1n;
    for (let i = 1; i < k; i++) {
        pow[i] = (n * pow[i - 1]) % MOD;
    }
}

function ggt(a, b) {
    if (a < b) return ggt(b, a);
    if (b === 0n) return a;
    return ggt(b, a % b);
}

function gcd(a, b) {
    return (a * b) / ggt(a, b);
}

function gcdRange(n) {
    let result = 1n;
    for (let i = 1n; i <= n; i++) {
        result = gcd(result, i);
    }
    return Number(result);
}

function solve(n, a, x, y, k, M) {
    init(BigInt(n), k);

    const gcdR = gcdRange(BigInt(k - 1));
    const r = Array.from({ length: gcdR }, () => new Array(k + 1).fill(0n));

    for (let i = 1; i <= k; i++) {
        for (let j = 0; j < gcdR; j++) {
            const jump = j - (j % (k + 1 - i));
            r[j][i] = (
                BigInt(n - 1) * r[j][i - 1] +
                r[jump][i - 1] +
                BigInt(j) * pow[i - 1]
            ) % MOD;
        }
    }

    let sum = 0n;
    const gcdRBig = BigInt(gcdR);
    const kBig = BigInt(k);

    for (let i = 0; i < n; i++) {
        sum += r[Number(a % gcdRBig)][k]
            + (((a / gcdRBig) * gcdRBig * kBig) % MOD) * pow[k - 1] % MOD;
        sum %= MOD;
        a = (a * x + y) % M;
    }

    console.log(sum.toString());
}

